def check_file_exists(filepath, check_name):
    """Check if a file exists."""
    if os.path.exists(filepath):
        return {"check_name": check_name, "passed": True, "message": f"File exists: {filepath}"}
    else:
        return {"check_name": check_name, "passed": False, "message": f"File missing: {filepath}"}


def check_file_not_empty(filepath, check_name):
    """Check if a file is not empty (has more than just headers)."""
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File missing: {filepath}"}

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()
        if len(lines) > 1:  # More than header row
            return {"check_name": check_name, "passed": True, "message": f"File is not empty: {filepath} ({len(lines)-1} data rows)"}
        else:
            return {"check_name": check_name, "passed": False, "message": f"File is empty (only header): {filepath}"}
    except Exception as e:
        return {"check_name": check_name, "passed": False, "message": f"Error reading file: {filepath} - {str(e)}"}


def check_required_columns(filepath, expected_columns, check_name):
    """Check if the file contains all expected columns."""
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File missing: {filepath}"}

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)

            if header is None:
                return {"check_name": check_name, "passed": False, "message": f"File has no header: {filepath}"}

            header_set = set(col.strip() for col in header)
            expected_set = set(expected_columns)

            missing = expected_set - header_set
            if missing:
                return {"check_name": check_name, "passed": False, "message": f"Missing columns in {filepath}: {missing}"}

            return {"check_name": check_name, "passed": True, "message": f"All expected columns present in {filepath}"}
    except Exception as e:
        return {"check_name": check_name, "passed": False, "message": f"Error reading columns: {filepath} - {str(e)}"}


def check_data_rows(filepath, check_name, min_rows=1):
    """Check that the file has at least min_rows data rows."""
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File missing: {filepath}"}

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader, None)

            if header is None:
                return {"check_name": check_name, "passed": False, "message": f"File has no header: {filepath}"}

            data_rows = sum(1 for _ in reader)

            if data_rows >= min_rows:
                return {"check_name": check_name, "passed": True, "message": f"Sufficient data rows in {filepath}: {data_rows} rows"}
            else:
                return {"check_name": check_name, "passed": False, "message": f"Insufficient data rows in {filepath}: {data_rows} rows (expected at least {min_rows})"}
    except Exception as e:
        return {"check_name": check_name, "passed": False, "message": f"Error counting rows: {filepath} - {str(e)}"}


def check_numeric_column(filepath, column_name, check_name):
    """Check that a specific column contains numeric values (for accessibility scores, etc.)."""
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File missing: {filepath}"}

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)

            if column_name not in reader.fieldnames:
                return {"check_name": check_name, "passed": False, "message": f"Column '{column_name}' not found in {filepath}"}

            all_numeric = True
            first_error = None
            count = 0

            for row in reader:
                count += 1
                try:
                    float(row[column_name])
                except (ValueError, TypeError):
                    all_numeric = False
                    if first_error is None:
                        first_error = f"Row {count}: '{row[column_name]}' is not numeric"
                    if count > 5:  # Only check first few rows
                        break

            if all_numeric:
                return {"check_name": check_name, "passed": True, "message": f"All values in '{column_name}' are numeric in {filepath}"}
            else:
                return {"check_name": check_name, "passed": False, "message": f"Non-numeric values found in '{column_name}' column of {filepath}: {first_error}"}
    except Exception as e:
        return {"check_name": check_name, "passed": False, "message": f"Error checking numeric column: {filepath} - {str(e)}"}


